def on_validate_error(self, value: str, error: InvalidResponse) -> None:
    """Called to handle validation error.

    Args:
        value (str): String entered by user.
        error (InvalidResponse): Exception instance the initiated the error.
    """
    if not self.console.markup:
        prompt_text = "The console does not support markup. Would you like to see the error message with markup? (yes/no)"
        response = self.console.input(prompt_text)
        if response.lower() == "yes":
            self.console.print(error)
        else:
            self.console.print(str(error.message))
    else:
        self.console.print(error)
